def transform(grid):
    h, w = len(grid), len(grid[0])
    a = [row[:] for row in grid]
    g = [row[:] for row in grid]
    marks = [(r,c) for r in range(h) for c in range(w) if a[r][c] in (2,4)]

    def neighbours(r,c):
        for dr,dc in ((0,-1),(0,1),(-1,0),(1,0)):
            rr,cc = r+dr,c+dc
            if 0 <= rr < h and 0 <= cc < w:
                yield dr,dc,rr,cc,a[rr][cc]

    def mark_colour(r,c):
        for dr,dc,rr,cc,v in neighbours(r,c):
            if v not in (0,2,4):
                return v
        for dr,dc in ((0,-1),(0,1),(-1,0),(1,0)):
            rr,cc = r+dr,c+dc
            while 0 <= rr < h and 0 <= cc < w:
                if a[rr][cc] not in (0,2,4):
                    return a[rr][cc]
                rr += dr
                cc += dc
        return 0

    colours = {(r,c):mark_colour(r,c) for r,c in marks}
    for (r,c),col in colours.items():
        g[r][c] = col

    # Pairs of 2s explicitly delimit a damaged stroke.
    for r,c in marks:
        if a[r][c] != 2:
            continue
        for dr,dc in ((0,1),(1,0)):
            rr,cc = r+dr,c+dc
            while 0 <= rr < h and 0 <= cc < w and a[rr][cc] == 0:
                rr += dr
                cc += dc
            if 0 <= rr < h and 0 <= cc < w and a[rr][cc] == 2:
                col = colours[(r,c)]
                x,y = r,c
                while True:
                    g[x][y] = col
                    if (x,y) == (rr,cc):
                        break
                    x += dr
                    y += dc

    # Small accidental gaps in otherwise straight strokes.
    for vertical in (False,True):
        b = [row[:] for row in g]
        for r in range(h):
            for c in range(w):
                col = b[r][c]
                if col == 0:
                    continue
                for d in (2,3):
                    rr,cc = (r+d,c) if vertical else (r,c+d)
                    if rr >= h or cc >= w or b[rr][cc] != col:
                        continue
                    cells = [(r+k,c) if vertical else (r,c+k) for k in range(1,d)]
                    if all(b[x][y] == 0 for x,y in cells):
                        for x,y in cells:
                            g[x][y] = col

    # At a crossing of two strokes, the long horizontal stroke is foremost.
    for r in range(h):
        for c in range(1,w-1):
            if g[r][c-1] != 0 and g[r][c-1] == g[r][c+1] and g[r][c] != g[r][c-1]:
                col = g[r][c-1]
                left = 0
                x = c-1
                while x >= 0 and g[r][x] == col:
                    left += 1
                    x -= 1
                right = 0
                x = c+1
                while x < w and g[r][x] == col:
                    right += 1
                    x += 1
                if left+right >= 6 or right > left:
                    g[r][c] = col

    # 4 is an arrow-like damaged end. Continue away from the principal
    # adjoining part of its stroke until the grid boundary.
    for r,c in marks:
        if a[r][c] != 4:
            continue
        col = colours[(r,c)]
        candidates = []
        for dr,dc,rr,cc,v in neighbours(r,c):
            if v == col:
                length = 0
                x,y = rr,cc
                while 0 <= x < h and 0 <= y < w and g[x][y] == col:
                    length += 1
                    x += dr
                    y += dc
                candidates.append((length,dr,dc))
        if not candidates:
            continue
        _,dr,dc = max(candidates)
        dr,dc = -dr,-dc
        rr,cc = r+dr,c+dc
        while 0 <= rr < h and 0 <= cc < w:
            g[rr][cc] = col
            rr += dr
            cc += dc
    return g
